import cn from 'classnames';
import { SeparatorProps } from './separator.types';
import './separator.scss';

export function Separator({ id, isDecorative, className }: SeparatorProps) {
  return (
    <div className={cn('separator', className)}>
      <div className="cmp-separator" id={id}>
        <hr
          className="cmp-separator__horizontal-rule"
          {...(isDecorative ? { 'aria-hidden': true, role: 'none' } : null)}
        />
      </div>
    </div>
  );
}

export default Separator;
